insert into public.test_series (id, title, title_hi, description, exam_category, is_free, price, created_at) values ('1018e460-055a-5c33-be8d-b38fd2220748', 'UPSC Prelims 2027 — Level 1: NCERT Foundation', 'UPSC प्रारंभिक परीक्षा 2027 — स्तर 1: एनसीईआरटी आधार', 'Foundation papers built on the NCERT textbooks: six GS Paper I subject tests (100 questions, 200 marks, 2 hours each), one GS foundation revision test, and three CSAT half papers (40 questions, 1 hour).', 'upsc', false, 0, '2026-10-11 10:05:00+05:30') on conflict (id) do update set title = excluded.title, title_hi = excluded.title_hi, description = excluded.description, created_at = excluded.created_at;
insert into public.test_series (id, title, title_hi, description, exam_category, is_free, price, created_at) values ('2bd2e098-2e48-4ebf-95a1-d86166211a77', 'UPSC Prelims 2027 — Level 2: Sectional Mastery', 'UPSC प्रारंभिक परीक्षा 2027 — स्तर 2: खंडवार दक्षता', 'Subject-by-subject papers on the UPSC pattern. 21 GS Paper I tests (100 questions, 200 marks, 2 hours; +2 / -0.66), one every Sunday at 9:30 am from 1 November 2026 to 21 March 2027, and 7 CSAT Paper II tests (80 questions, 200 marks, 2 hours; +2.5 / -0.83), every third Saturday at 2:30 pm from 7 November 2026.', 'upsc', false, 0, '2026-10-11 10:04:00+05:30') on conflict (id) do update set title = excluded.title, title_hi = excluded.title_hi, description = excluded.description, created_at = excluded.created_at;
insert into public.test_series (id, title, title_hi, description, exam_category, is_free, price, created_at) values ('5a01546b-dddb-5fca-b584-3e0808b9d8ea', 'UPSC Prelims 2027 — Level 3: Integration & Precision', 'UPSC प्रारंभिक परीक्षा 2027 — स्तर 3: समेकन और सटीकता', 'Late March to April 2027: six comprehensive GS Paper I tests across the whole syllabus (100 questions, 2 hours) and four harder CSAT Paper II tests (80 questions, 2 hours).', 'upsc', false, 0, '2026-10-11 10:03:00+05:30') on conflict (id) do update set title = excluded.title, title_hi = excluded.title_hi, description = excluded.description, created_at = excluded.created_at;
insert into public.test_series (id, title, title_hi, description, exam_category, is_free, price, created_at) values ('d2d3da6f-d92c-5654-8c12-a884dac76be0', 'UPSC Prelims 2027 — Level 4: Full-Length Simulation', 'UPSC प्रारंभिक परीक्षा 2027 — स्तर 4: पूर्ण परीक्षा-अनुकरण', 'April to May 2027, exam-day conditions: ten GS Paper I simulators and nine CSAT Paper II simulators, two a week in the final stretch, the last one a week before the Prelims.', 'upsc', false, 0, '2026-10-11 10:02:00+05:30') on conflict (id) do update set title = excluded.title, title_hi = excluded.title_hi, description = excluded.description, created_at = excluded.created_at;
insert into public.test_series (id, title, title_hi, description, exam_category, is_free, price, created_at) values ('24804bda-6cda-5cc6-88db-f1a1b4f2399a', 'UPSC Prelims 2027 — Current Affairs: Quarterly Tests', 'UPSC प्रारंभिक परीक्षा 2027 — समसामयिकी: त्रैमासिक टेस्ट', 'Five current-affairs GS Paper I tests (100 questions, 2 hours), one for each quarter from January-March 2026 to January-March 2027, each linking the quarter''s events to the static syllabus.', 'upsc', false, 0, '2026-10-11 10:01:00+05:30') on conflict (id) do update set title = excluded.title, title_hi = excluded.title_hi, description = excluded.description, created_at = excluded.created_at;
